import "server-only";

import { createHash, randomBytes } from "node:crypto";

/**
 * Opaque guest cart tokens.
 *
 * A guest has no account, so the only thing that can identify their cart is something the
 * server hands their browser. That makes the token a **bearer credential** in exactly the
 * way a session token is, and it is treated identically:
 *
 * - 32 random bytes (256 bits) rendered as hex, generated by `randomBytes`, so it cannot be
 *   guessed or enumerated;
 * - the raw value is sent to the browser once, inside an `HttpOnly` cookie
 *   (`lib/cart/cookies.ts`), and never appears in a URL, a payload or a log;
 * - only a SHA-256 digest is stored (`carts.guest_token_hash`), so a database leak cannot
 *   be replayed as ownership of someone else's cart.
 *
 * ## Why the digest is domain-separated
 *
 * `hashGuestCartToken` hashes a prefixed string, not the bare token. If a session token and
 * a guest cart token were ever byte-identical, the two digests would be identical too, and
 * a digest copied from one table would resolve a row in the other. Prefixing each domain
 * (`customer-session\0…`, `guest-cart\0…`) makes the two digest spaces disjoint. The
 * `\0` separator is unambiguous because neither token alphabet contains a NUL byte.
 *
 * SHA-256, not Argon2, is correct here for the same reason it is correct for sessions: the
 * input is 256 bits of uniform entropy, so there is nothing to brute-force and verification
 * must stay cheap.
 */

/** Distinguishes a guest-cart digest from any other digest derived from the same token. */
const GUEST_CART_TOKEN_DOMAIN = "chronospeed:guest-cart-token:v1";

/** 32 random bytes as hex — 64 characters, 256 bits of entropy. */
export function generateGuestCartToken(): string {
  return randomBytes(32).toString("hex");
}

/** The value stored in `carts.guest_token_hash`. Never send this to a client. */
export function hashGuestCartToken(token: string): string {
  return createHash("sha256")
    .update(`${GUEST_CART_TOKEN_DOMAIN}\0${token}`, "utf8")
    .digest("hex");
}

/**
 * Guest cart expiry.
 *
 * `days` is passed in rather than read from `env` here, so this module stays a pure,
 * directly testable function with no configuration dependency — the same shape
 * `lib/auth/tokens.ts` uses.
 */
export function guestCartExpiresAt(days: number, now = Date.now()): Date {
  return new Date(now + days * 24 * 60 * 60 * 1000);
}